def retry_on_exception(retries: int = 3 ,delay: float = 0.5): 
    def decorator(func): 
        @wraps(func) 
        def wrapper(*args ,**kwargs): 
            last_exc = None 
            for attempt in range(retries): 
                try: 
                    return func(*args ,**kwargs) 
                except Exception as exc: 
                    last_exc = exc 
                    logger.exception(str(exc)) 
                    time.sleep(delay) 
            raise last_exc 
        return wrapper 
    return decorator 
