def secure_save_file(file_storage, upload_dir: str) -> Tuple[str ,int ,str]: 
    filename = secure_filename(file_storage.filename) 
    if not allowed_file(filename): 
        raise ValueError ("File type not allowed") 
    unique_name = f"{uuid.uuid4().hex}_{filename}" 
    path = os.path.join(upload_dir ,unique_name) 
    file_storage.save(path) 
    size = os.path.getsize(path) 
    mimetype = file_storage.mimetype or mimetypes.guess_type(filename)[0] or "application/octet-stream" 
    return unique_name ,size ,mimetype 
def compute_hmac_sha256(key: bytes ,message: bytes) -> str: 
    return hmac.new(key ,message ,hashlib.sha256).hexdigest() 
