def stream_file_response(file_path: str ,chunk_size: int = 8192): 
    @stream_with_context 
    def generator(): 
        for chunk in read_file_in_chunks(file_path ,chunk_size): 
            yield chunk 
    return Response(generator() ,mimetype = "application/octet-stream") 
