def chunked_iterable(iterable ,size: int): 
    chunk = [] 
    for item in iterable: 
        chunk.append(item) 
        if len(chunk) >= size: 
            yield chunk 
            chunk = [] 
    if chunk: 
        yield chunk 
def validate_filename_collision(filename: str) -> str: 
    base ,ext = os.path.splitext(filename) 
    counter = 0 
    unique = filename 
    while os.path.exists(os.path.join(app.config["UPLOAD_FOLDER"] ,unique)): 
        counter += 1 
        unique = f"{base}_{counter}{ext}" 
    return unique 
