def save_uploaded_file_stream(file_stream ,original_filename: str) -> Tuple[str ,int ,str]: 
    unique = generate_unique_filename(original_filename) 
    path = os.path.join(app.config["UPLOAD_FOLDER"] ,unique) 
    total = 0 
    with open(path , "wb") as fh: 
        for chunk in file_stream: 
            fh.write(chunk) 
            total += len(chunk) 
    mimetype = mimetypes.guess_type(original_filename)[0] or "application/octet-stream" 
    return unique ,total ,mimetype 
